function EXTRA(R,ICON){
 /* hook: a motor driving a pump rotor on two bearings, and the same shaft bowed into whirl */
 ICON.sdPump=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${SD_box(0,0,380,170,{fill:'#FFFFFF',st:SD_GREY,sw:3,r:18})}
  <rect x="20" y="50" width="80" height="64" rx="8" fill="${BLU}" fill-opacity=".85"/>${SD_T(60,90,'motor',{fs:20,fw:800,a:'middle',fill:'#FFFFFF'})}
  <rect x="100" y="76" width="250" height="12" rx="3" fill="${SD_STEEL}"/>${SD_brg(150,88,10)}${SD_brg(320,88,10)}
  <rect x="226" y="46" width="22" height="72" rx="4" fill="${SD_LIGHT}" stroke="${SD_DARK}" stroke-width="3"/>
  ${SD_T(190,36,'stress check ✓',{fs:24,fw:800,fill:GRN})}${SD_T(190,152,'pump rotor on two bearings',{fs:20,a:'middle',fill:SD_GREY})}</g>`;
 ICON.sdWhirl=(x,y)=>{const pts=SD_sag(100,70,250,34);return `<g transform="translate(${x-190} ${y-85})">${SD_box(0,0,380,170,{fill:'#FFFFFF',st:RED,sw:3,r:18})}
  <rect x="20" y="40" width="80" height="64" rx="8" fill="${BLU}" fill-opacity=".85"/>${SD_T(60,80,'motor',{fs:20,fw:800,a:'middle',fill:'#FFFFFF'})}
  ${SD_L(100,70,350,70,SD_GREY,2,'stroke-dasharray="6 5"')}${SD_poly(pts,SD_STEEL,10)}${SD_brg(100,76,10)}${SD_brg(350,76,10)}
  <ellipse cx="225" cy="88" rx="16" ry="34" fill="none" stroke="${RED}" stroke-width="3" stroke-dasharray="6 4"/>
  <rect x="214" y="68" width="22" height="64" rx="4" fill="${SD_LIGHT}" stroke="${SD_DARK}" stroke-width="3"/>
  ${SD_T(260,150,'one speed: whirl',{fs:24,fw:800,a:'middle',fill:RED})}</g>`};
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.sdRcTe=(x,y)=>{let s=`<rect x="20" y="40" width="380" height="18" rx="4" fill="${SD_STEEL}"/>`+SD_brg(40,58,14)+SD_brg(380,58,14)+
  `<rect x="128" y="0" width="34" height="100" rx="6" fill="${SD_LIGHT}" stroke="${SD_DARK}" stroke-width="3"/>`+SD_arrow(136,104,136,150,GRN,5,16)+SD_arrow(154,104,154,150,GRN,5,16);
  /* moment diagram of the first worked example: 0 at A (x 40), 382 N·m at 300 mm (x 145), 0 at B (x 380); 0.32 px per N·m */
  s+=`<polygon points="40,200 145,${200+382*0.32} 380,200" fill="${BLU}" fill-opacity=".2" stroke="${BLU}" stroke-width="4" stroke-linejoin="round"/>`+SD_L(30,200,390,200,SD_DARK,2)+
   SD_T(160,200+382*0.32+30,'M = 382 N·m',{fs:24,fw:800,fill:BLU})+SD_T(260,160,'T = 191 N·m',{fs:24,fw:800,fill:ORG});
  return `<g transform="translate(${x-210} ${y-170})">${s}</g>`};
 ICON.sdRcTwist=(x,y)=>{let s=`<rect x="20" y="70" width="330" height="120" rx="10" fill="${SD_LIGHT}" stroke="${SD_STEEL}" stroke-width="4"/>`+`<ellipse cx="350" cy="130" rx="26" ry="60" fill="#FFFFFF" stroke="${SD_STEEL}" stroke-width="4"/>`+
  SD_L(20,96,350,96,SD_GREY,3,'stroke-dasharray="9 6"')+SD_L(20,96,350,160,ORG,7)+
  `<path d="M366,60 A44,70 0 0 1 366,200" fill="none" stroke="${ORG}" stroke-width="5"/>`+SD_arrow(370,192,354,212,ORG,5,16)+SD_T(250,120,'θ',{fs:34,fw:800,fill:ORG})+
  SD_T(20,250,'strength: 43.3 mm',{fs:24,fw:700,fill:SD_GREY})+SD_T(20,290,'rigidity: 65.8 mm → 70',{fs:26,fw:800,fill:ORG});
  return `<g transform="translate(${x-230} ${y-180}) scale(1.15)">${s}</g>`};
 ICON.sdRcWhirl=(x,y)=>{/* y/e against r = N/Nc, 0 to 2, ζ = 0.1, clipped at 5 */const W=380,Hh=240,mx=r=>20+r/2*W,my=v=>Hh-Math.min(v,5)/5*(Hh-20);
  const pts=SD_range(0,2,160).map(r=>[mx(r),my(SD_whirl(r))]);
  let s=`<rect x="${mx(.75)}" y="20" width="${mx(1.25)-mx(.75)}" height="${Hh-20}" fill="${GRN}" fill-opacity=".16"/>`+SD_L(20,Hh,20+W,Hh,SD_DARK,3)+SD_L(20,20,20,Hh,SD_DARK,3)+
   SD_poly(pts,GRN,5)+SD_L(mx(1),14,mx(1),Hh,RED,3,'stroke-dasharray="6 4"')+SD_T(mx(1),Hh+32,'Nc',{fs:26,fw:800,a:'middle',fill:RED})+
   SD_L(20,my(1),20+W,my(1),SD_GREY,2,'stroke-dasharray="4 5"')+SD_T(20+W,my(1)+28,'y → e',{fs:22,fw:700,a:'end',fill:SD_GREY})+SD_T(26,40,'whirl',{fs:22,fw:700,fill:SD_GREY})+SD_T(20+W,Hh+32,'speed',{fs:22,a:'end',fill:SD_GREY});
  return `<g transform="translate(${x-210} ${y-150})">${s}</g>`};
}
